No

### Description

```ts
interface Base {
  type: 'foo' | 'bar'
}

interface Foo extends Base {
  type: 'foo';
  foo: string;
}

interface Bar extends Base {
  type: 'bar';
  bar: number;
}

@Component({
  selector: 'app-root',
  standalone: true,
  template: `
@switch (v.type) {
  @case ('bar') {
    {{ v.bar }}
  }

  @case ('foo') {
    {{ v.foo }}
  }

  @default {
    Default
  }
}
  `
})
export class AppComponent {
   v: Foo | Bar = { type: 'foo', foo: 'foo' };
}
```

